<script setup lang="ts">
import {computed} from 'vue';import {useRoute} from 'vue-router';import {ArrowLeft,ArrowUpRight} from 'lucide-vue-next';import type {LoanDetail} from '../api';import {useLoans} from '../composables/poll';import {money,remaining,sumMinor,time} from '../money';import DataState from '../components/DataState.vue';import StatusBadge from '../components/StatusBadge.vue';
const route=useRoute();const path=computed(()=>'/loans/'+encodeURIComponent(String(route.params.reference)));const {data,error,loading,updatedAt}=useLoans<LoanDetail>(path);
</script>
<template><RouterLink to="/loans" class="back-link"><ArrowLeft :size="15"/>Back to loans</RouterLink><div class="page-title"><div><p class="eyebrow">{{data?.loan.customer??'LOAN DETAIL'}}</p><h1>{{route.params.reference}}</h1><p class="muted">Fictional monthly reducing-balance loan · 12% annual · Monthly payment 9,000 THB</p></div><RouterLink to="/simulator" class="action-link">Simulate a payment <ArrowUpRight :size="17"/></RouterLink></div><DataState :loading="loading" :error="error" :updated-at="updatedAt"/>
<div class="stat-grid"><div class="stat-card"><span>Actual principal outstanding</span><strong class="money-stat">{{money(data?.loan.outstandingPrincipal)}}</strong><small>Opening: {{money(data?.loan.openingPrincipal)}}</small></div><div class="stat-card"><span>Principal repaid</span><strong class="money-stat">{{money(data?.loan.paidPrincipal)}}</strong></div><div class="stat-card"><span>Interest paid</span><strong class="money-stat">{{money(data?.loan.paidInterest)}}</strong></div><div class="stat-card"><span>Outstanding due interest</span><strong class="money-stat">{{money(data?.loan.dueInterest)}}</strong></div><div class="stat-card"><span>Unapplied credit · review</span><strong class="money-stat amber-text">{{money(data?.loan.unappliedCredit)}}</strong></div><div class="stat-card"><span>Next unpaid installment</span><strong>{{data?.loan.nextDueDate??'Cleared'}}</strong><small>Month-end dates preserved</small></div></div>
<section class="panel"><div class="panel-heading"><div><h3>Contractual installment schedule</h3><p>Fixed at origination. Scheduled closing principal differs from actual outstanding principal.</p></div></div><el-table :data="data?.installments??[]"><el-table-column prop="number" label="#" width="50"/><el-table-column prop="dueDate" label="Due date" width="120"/><el-table-column label="Scheduled opening" min-width="175"><template #default="{row}">{{money(row.scheduledOpeningPrincipal)}}</template></el-table-column><el-table-column label="Interest" min-width="145"><template #default="{row}">{{money(row.interest)}}</template></el-table-column><el-table-column label="Principal" min-width="145"><template #default="{row}">{{money(row.principal)}}</template></el-table-column><el-table-column label="Payment" min-width="145"><template #default="{row}">{{money(sumMinor(row.interest,row.principal))}}</template></el-table-column><el-table-column label="Amount paid" min-width="145"><template #default="{row}">{{money(sumMinor(row.paidInterest,row.paidPrincipal))}}</template></el-table-column><el-table-column label="Remaining" min-width="145"><template #default="{row}">{{money(remaining(row.interest,row.principal,row.paidInterest,row.paidPrincipal))}}</template></el-table-column><el-table-column label="Scheduled closing" min-width="175"><template #default="{row}">{{money(row.scheduledClosingPrincipal)}}</template></el-table-column></el-table></section>
<section class="panel"><div class="panel-heading"><h3>Payment history & allocations</h3></div><el-table :data="data?.payments??[]"><el-table-column prop="bankTransactionId" label="Original bank identity" min-width="280"/><el-table-column label="Paid at (Bangkok)" min-width="200"><template #default="{row}">{{time(row.paidAt)}}</template></el-table-column><el-table-column label="Amount" min-width="160"><template #default="{row}">{{money(row.amountMinor)}}</template></el-table-column><el-table-column label="Outcome" min-width="160"><template #default="{row}"><StatusBadge :status="row.status"/></template></el-table-column><el-table-column label="Allocation" min-width="240"><template #default="{row}"><div v-for="(a,index) in row.allocations" :key="index">#{{a.installmentNumber}}: {{money(a.interest)}} interest / {{money(a.principal)}} principal</div></template></el-table-column></el-table></section>
<section class="panel"><div class="panel-heading"><h3>Immutable balanced journals</h3><span class="eyebrow">POSTED LEDGER</span></div><el-collapse><el-collapse-item v-for="journal in data?.journals" :key="journal.id" :title="journal.kind+' · '+time(journal.postedAt)"><el-table :data="journal.postings"><el-table-column prop="account" label="Account"/><el-table-column label="Debit"><template #default="{row}">{{money(row.debit)}}</template></el-table-column><el-table-column label="Credit"><template #default="{row}">{{money(row.credit)}}</template></el-table-column></el-table></el-collapse-item></el-collapse></section></template>
